    @register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
    @DistProfiler.annotate(color="blue", role="actor_compute_log_prob")
    def compute_log_prob(self, data: DataProto):
        # when is_lora is True, we use the actor without lora applied to calculate the log_prob
        # which is mostly used for ref log_prob calculation
        assert self._is_actor
        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)

        # Support all hardwares
        from contextlib import nullcontext

        is_lora = data.meta_info.pop("is_lora", False)
        adapter_ctx = self.actor.actor_module.disable_adapter() if is_lora else nullcontext()
        peft_model = getattr(self.actor, "actor_module", None)
        if self.rank == 0:
            with contextlib.suppress(Exception):
                debug_path = _write_rollout_policy_debug(
                    "actor_compute_log_prob",
                    {
                        "experiment_name": str(getattr(self, "experiment_name", "unknown_exp")),
                        "rank": int(self.rank),
                        **_actor_adapter_state_payload(peft_model, {"is_lora_flag": bool(is_lora)}),
                    },
                )
                print(f"[DEBUG actor compute_log_prob policy] wrote {debug_path}")
        # we should always recompute old_log_probs when it is HybridEngine
        data.meta_info["micro_batch_size"] = self.config.rollout.log_prob_micro_batch_size_per_gpu
        data.meta_info["max_token_len"] = self.config.rollout.log_prob_max_token_len_per_gpu
        data.meta_info["use_dynamic_bsz"] = self.config.rollout.log_prob_use_dynamic_bsz
        data.meta_info["temperature"] = self.config.rollout.temperature
        # perform recompute log_prob
        with self.ulysses_sharding_manager:
            with adapter_ctx:
                output, entropys = self.actor.compute_log_prob(data=data, calculate_entropy=True)
            output = DataProto.from_dict(
                tensors={"old_log_probs": output, "entropys": entropys},
                meta_info={"temperature": self.config.rollout.temperature},
            )

        output = output.to("cpu")

        # https://pytorch.org/docs/stable/notes/fsdp.html#fsdp-notes
        # unshard the root FSDP module
        if self.world_size > 1 and fsdp_version(self.actor.actor_module) == 1:
            self.actor.actor_module._handle.reshard(True)

        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)
            log_gpu_memory_usage("After offload actor model during compute_log_prob", logger=logger)

        return output

    def _disable_lora_dropout(self, model) -> int:
        disabled = 0
        for module in model.modules():
            lora_dropout = getattr(module, "lora_dropout", None)
            if lora_dropout is None:
                continue
            if isinstance(lora_dropout, dict):
                values = lora_dropout.values()
            else:
                values = getattr(lora_dropout, "values", lambda: [])()
            for dropout_layer in values:
                if hasattr(dropout_layer, "p") and dropout_layer.p != 0.0:
                    dropout_layer.p = 0.0
                    disabled += 1
        return disabled

    def _maybe_freeze_lora_A(self, model) -> None:
        if not self.config.model.get("freeze_lora_A", False):
            return
        frozen = 0
        for name, param in model.named_parameters():
            if "lora_A" in name:
                param.requires_grad = False
                frozen += 1
        if self.rank == 0:
            print(f"[LoRA] Frozen lora_A parameters: {frozen}")

    def _collect_svd_init_pretrained_rollout_params(self, peft_config) -> dict[str, torch.Tensor]:
        from transformers import AutoModelForCausalLM

        pretrained_path = getattr(peft_config, "base_model_name_or_path", None) if peft_config is not None else None
        if not pretrained_path:
            raise ValueError("SVD-init rollout sync requires peft_config.base_model_name_or_path")

        local_pretrained_path = copy_to_local(pretrained_path, use_shm=self.config.model.get("use_shm", False))
        if self.rank == 0:
            logger.info(
                "Rollout first sync for SVD-init adapters now loads the original pretrained base model from %s",
                local_pretrained_path,
            )

        pretrained_model = AutoModelForCausalLM.from_pretrained(
            pretrained_model_name_or_path=local_pretrained_path,
            torch_dtype=torch.float32,
            trust_remote_code=self.config.model.get("trust_remote_code", False),
            device_map="cpu",
        )
        try:
            return {name: param.detach().cpu() for name, param in pretrained_model.state_dict().items()}
        finally:
            del pretrained_model

    @contextmanager
    def _svd_init_adapter_ctx(self):
        """Temporarily switch to the frozen initial PiSSA/MiLoRA adapter.

        For SVD-init adapters the residual base stores W_res, so correct base-model KL
        needs W_pretrained = W_res + delta_init. A dedicated frozen adapter gives that
        behavior without triggering FSDP summon_full_params/all-gathers mid-step.
        """
        peft_model = getattr(self.actor, "actor_module", None)
        adapter_name = self._svd_ref_adapter_name

        if peft_model is None or adapter_name is None:
            if self.rank == 0:
                logger.warning(
                    "[SVD-init ref] Frozen reference adapter missing: falling back to current adapter. "
                    "Base-model KL may be inaccurate."
                )
            yield
            return

        previous_adapter = peft_model.active_adapters[0] if peft_model.active_adapters else "default"
        peft_model.base_model.set_adapter(adapter_name, inference_mode=True)
        peft_model.active_adapter = adapter_name
        try:
            yield
        finally:
            peft_model.base_model.set_adapter(previous_adapter, inference_mode=False)
            peft_model.active_adapter = previous_adapter

    def _compute_base_log_prob_from_actor(self, data: DataProto, output_key: str) -> DataProto:
        if self._is_lora:
            if self._is_svd_init:
                # SVD-init (PiSSA/MiLoRA): base = W_pretrained = W_res + A_init @ B_init.
                with self._svd_init_adapter_ctx():
                    data.meta_info["micro_batch_size"] = self.config.rollout.log_prob_micro_batch_size_per_gpu
                    data.meta_info["max_token_len"] = self.config.rollout.log_prob_max_token_len_per_gpu
                    data.meta_info["use_dynamic_bsz"] = self.config.rollout.log_prob_use_dynamic_bsz
                    data.meta_info["temperature"] = self.config.rollout.temperature
                    if self._is_offload_param:
                        load_fsdp_model_to_gpu(self.actor_module_fsdp)
                    with self.ulysses_sharding_manager:
                        output, _ = self.actor.compute_log_prob(data=data, calculate_entropy=False)
                    if self._is_offload_param:
                        offload_fsdp_model_to_cpu(self.actor_module_fsdp)
                return DataProto.from_dict(tensors={output_key: output.to("cpu")})

            # Standard LoRA/plus/b0: disable_adapter() exposes the underlying base model.
            data.meta_info["is_lora"] = True
            data = self.compute_log_prob(data)
            return DataProto.from_dict(tensors={output_key: data.batch["old_log_probs"]})

        data.meta_info["micro_batch_size"] = self.config.rollout.log_prob_micro_batch_size_per_gpu
        data.meta_info["max_token_len"] = self.config.rollout.log_prob_max_token_len_per_gpu
        data.meta_info["use_dynamic_bsz"] = self.config.rollout.log_prob_use_dynamic_bsz
        data.meta_info["temperature"] = self.config.rollout.temperature
        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)
        with self.ulysses_sharding_manager:
            output, _ = self.actor.compute_log_prob(data=data, calculate_entropy=False)
        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)
        return DataProto.from_dict(tensors={output_key: output.to("cpu")})

    @register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
    @DistProfiler.annotate(color="olive", role="ref_compute_log_prob")
    def compute_ref_log_prob(self, data: DataProto):
        if self._is_lora:
            return self._compute_base_log_prob_from_actor(data, output_key="ref_log_prob")
        assert self._is_ref
        # else:
        # otherwise, the class have a standalone ref model

        micro_batch_size = self.config.ref.log_prob_micro_batch_size_per_gpu
        data.meta_info["micro_batch_size"] = micro_batch_size
        data.meta_info["temperature"] = self.config.rollout.temperature
        data.meta_info["max_token_len"] = self.config.ref.log_prob_max_token_len_per_gpu
        data.meta_info["use_dynamic_bsz"] = self.config.ref.log_prob_use_dynamic_bsz
        with self.ulysses_sharding_manager:
            data = data.to("cpu")  # data will to device with each micro batch on ref.compute_log_prob
            output, _ = self.ref_policy.compute_log_prob(data=data, calculate_entropy=False)
            output = DataProto.from_dict(tensors={"ref_log_prob": output})

        output = output.to("cpu")

        # https://pytorch.org/docs/stable/notes/fsdp.html#fsdp-notes
        # unshard the root FSDP module
        if self.world_size > 1:
            if fsdp_version(self.ref_policy.actor_module) == 1:
                self.ref_policy.actor_module._handle.reshard(True)
            elif fsdp_version(self.ref_policy.actor_module) == 2:
                self.ref_policy.actor_module.reshard()

        return output

    @register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
    @DistProfiler.annotate(color="teal", role="base_ref_compute_log_prob")
    def compute_base_ref_log_prob(self, data: DataProto):
        assert self._is_actor, "base-model log prob can only be computed on actor workers"
        return self._compute_base_log_prob_from_actor(data, output_key="base_ref_log_prob")

    @register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
    @DistProfiler.annotate(color="teal", role="expected_svd_base_ref_compute_log_prob")
    def compute_expected_svd_base_ref_log_prob(self, data: DataProto):
        """Compute the independently correct pretrained reference for validation health checks."""
        assert self._is_actor, "expected base-model log prob can only be computed on actor workers"
        if not (self._is_lora and self._is_svd_init):
            return self._compute_base_log_prob_from_actor(data, output_key="expected_base_ref_log_prob")

        data.meta_info["micro_batch_size"] = self.config.rollout.log_prob_micro_batch_size_per_gpu
        data.meta_info["max_token_len"] = self.config.rollout.log_prob_max_token_len_per_gpu
        data.meta_info["use_dynamic_bsz"] = self.config.rollout.log_prob_use_dynamic_bsz
        data.meta_info["temperature"] = self.config.rollout.temperature
        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)
        with self._svd_init_adapter_ctx():
            with self.ulysses_sharding_manager:
                output, _ = self.actor.compute_log_prob(data=data, calculate_entropy=False)
        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)
        return DataProto.from_dict(tensors={"expected_base_ref_log_prob": output.to("cpu")})

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def save_checkpoint(self, local_path, hdfs_path=None, global_step=0, max_ckpt_to_keep=None):
        from verl.utils.logger import log_with_rank

        # only support save and load ckpt for actor
        assert self._is_actor

        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)

        self.checkpoint_manager.save_checkpoint(
            local_path=local_path, hdfs_path=hdfs_path, global_step=global_step, max_ckpt_to_keep=max_ckpt_to_keep
        )
        dist.barrier()

        if self._is_lora and hasattr(getattr(self, "actor_module", self.actor_module_fsdp), "peft_config"):
            lora_save_path = os.path.join(local_path, "lora_adapter")
            peft_model = getattr(self, "actor_module", self.actor_module_fsdp)
            peft_config = {}
            if dist.get_rank() == 0:
                os.makedirs(lora_save_path, exist_ok=True)
                peft_config = asdict(peft_model.peft_config.get("default", {}))
                peft_config["task_type"] = peft_config["task_type"].value
                peft_config["peft_type"] = peft_config["peft_type"].value
                peft_config["target_modules"] = list(peft_config["target_modules"])
            try:
                if fsdp_version(self.actor_module_fsdp) > 0:
                    self.actor_module_fsdp = self.actor_module_fsdp.to(get_device_name())
                    lora_params = layered_summon_lora_params(self.actor_module_fsdp)
                    if dist.get_rank() == 0:
                        save_file(lora_params, os.path.join(lora_save_path, "adapter_model.safetensors"))
                        with open(os.path.join(lora_save_path, "adapter_config.json"), "w", encoding="utf-8") as f:
                            json.dump(peft_config, f, ensure_ascii=False, indent=4)
            except Exception as e:
                log_with_rank(
                    f"Save LoRA Adapter Error ({e})", rank=dist.get_rank(), logger=logger, log_only_rank_0=True
                )

            dist.barrier()
            log_with_rank(
                f"[rank-{self.rank}]: Saved LoRA adapter to: {lora_save_path}",
                rank=dist.get_rank(),
                logger=logger,
                log_only_rank_0=True,
            )

        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def load_checkpoint(self, local_path, hdfs_path=None, del_local_after_load=False):
        assert self._is_actor or (not self._is_actor and self._is_rollout), (
            f"Checkpoint loading is only supported for Actor or standalone Rollout Workers, but got "
            f"{self._is_actor} and {self._is_rollout}"
        )

        # No checkpoint to load, just offload the model and optimizer to CPU
        if local_path is None:
            if self._is_offload_param:
                offload_fsdp_model_to_cpu(self.actor_module_fsdp)
            if self._is_offload_optimizer:
                offload_fsdp_optimizer(self.actor_optimizer)
            return

        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)

        self.checkpoint_manager.load_checkpoint(
            local_path=local_path, hdfs_path=hdfs_path, del_local_after_load=del_local_after_load
        )

        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)

        if self._is_offload_optimizer:
            offload_fsdp_optimizer(self.actor_optimizer)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def start_profile(self, **kwargs) -> None:
        """Start profiling for the current rank in the current training step."""
        self.profiler.start(**kwargs)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def stop_profile(self) -> None:
        """Stop profiling for the current rank in the current training step."""
        self.profiler.stop()

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def dump_memory_snapshot(self, tag: str = "manual", sub_dir: str = None) -> None:
        """Manually trigger a CUDA memory snapshot dump on all ranks."""
        # Memory snapshot is now handled by the profiler system
        # This method is kept for backward compatibility but delegates to profiler
        if hasattr(self, "profiler") and hasattr(self.profiler, "_impl"):
            try:
                # Try to use the profiler's memory snapshot functionality
                if hasattr(self.profiler._impl, "sampler"):
                    out_dir = OmegaConf.select(self.config, "actor.profiler.save_path") or "."
                    self.profiler._impl.sampler.dump_memory_snapshot(out_dir=out_dir, tag=tag, sub_dir=sub_dir)
            except Exception:
                # silently ignore if profiler doesn't support memory snapshots
                pass


class CriticWorker(Worker, DistProfilerExtension):
    def __init__(self, config: FSDPCriticConfig):
        Worker.__init__(self)
        omega_profiler_config = config.get("profiler", {})
        profiler_config = omega_conf_to_dataclass(omega_profiler_config, dataclass_type=ProfilerConfig)
        if omega_profiler_config.get("tool", None) in ["npu", "nsys", "torch", "torch_memory"]:
            tool_config = omega_conf_to_dataclass(
                omega_profiler_config.get("tool_config", {}).get(omega_profiler_config.get("tool"))
            )
        else:
            tool_config = None
        DistProfilerExtension.__init__(
            self, DistProfiler(rank=self.rank, config=profiler_config, tool_config=tool_config)
        )
        import torch.distributed

        self.config = config
        if not torch.distributed.is_initialized():
            torch.distributed.init_process_group(
                backend=get_nccl_backend(),
                timeout=datetime.timedelta(seconds=self.config.get("nccl_timeout", 600)),
                init_method=os.environ.get("DIST_INIT_METHOD", None),
            )
        self.config: FSDPCriticConfig = config

        # build device mesh for Ulysses Sequence Parallel
        world_size = torch.distributed.get_world_size()
        from torch.distributed.device_mesh import init_device_mesh

        fsdp_size = self.config.model.fsdp_config.fsdp_size
        self.device_mesh = create_device_mesh(world_size=world_size, fsdp_size=fsdp_size)

        self.ulysses_device_mesh = None
        self.ulysses_sequence_parallel_size = self.config.get("ulysses_sequence_parallel_size", 1)
        dp = world_size // self.ulysses_sequence_parallel_size
        if self.ulysses_sequence_parallel_size > 1:
            self.ulysses_device_mesh = init_device_mesh(
                device_name, mesh_shape=(dp, self.ulysses_sequence_parallel_size), mesh_dim_names=["dp", "sp"]
            )

        # create training dispatch
        if self.ulysses_device_mesh is not None:
            is_collect = self.ulysses_device_mesh["sp"].get_local_rank() == 0
            self._register_dispatch_collect_info(
                "critic", dp_rank=self.ulysses_device_mesh["dp"].get_local_rank(), is_collect=is_collect
            )
        else:
            self._register_dispatch_collect_info("critic", dp_rank=self.rank, is_collect=True)

        self.ulysses_sharding_manager = FSDPUlyssesShardingManager(self.ulysses_device_mesh)

        # set FSDP offload params
        self._is_offload_param = self.config.model.fsdp_config.param_offload
        self._is_offload_optimizer = self.config.model.fsdp_config.optimizer_offload

        # normalize config
        self.config.ppo_mini_batch_size *= self.config.rollout_n
        self.config.ppo_mini_batch_size //= torch.distributed.get_world_size() // self.ulysses_sequence_parallel_size

def fsdp2_load_full_state_dict(model: torch.nn.Module, full_state: dict, device_mesh=None, cpu_offload=None):
    """
    Loads the full state dict (could be only on rank 0) into the sharded model. This is done by broadcasting the
    parameters from rank 0 to all other ranks. This function modifies the model in-place.

    Args:
        model (`torch.nn.Module`): The model to load the state dict into
        full_state (`dict`): The full state dict to load, can only be on rank 0
    """

    if version.parse(torch.__version__) >= version.parse("2.7.0"):
        from torch.distributed.checkpoint.state_dict import StateDictOptions, set_model_state_dict
    else:
        # official torch 2.6.0 set_model_state_dict API leads to OOM
        # use torch 2.7.0 copy from verl/third_party/torch/distributed/checkpoint
        from verl.third_party.torch.distributed.checkpoint.state_dict import StateDictOptions, set_model_state_dict

    # To broadcast, it needs to be instantiated in the GPU.
    if dist.get_rank() == 0:
        model = model.to(device=get_device_id(), non_blocking=True)
    else:
        model = model.to_empty(device=get_device_id())

    cpu_offload = cpu_offload is not None
    options = StateDictOptions(full_state_dict=True, cpu_offload=cpu_offload, broadcast_from_rank0=True)
    set_model_state_dict(model, full_state, options=options)

    # rotary_emb is not in state_dict, so we need to broadcast it manually
    for name, buf in model.named_buffers():
        dist.broadcast(buf, src=0)

    if cpu_offload:
        model.to("cpu", non_blocking=True)
        for buf in model.buffers():
            buf.data = buf.data.to(get_device_id())


@contextmanager
def maybe_patch_fsdp_module(model):
    if fully_shard_module is None:
        yield
        return

    orig_fsdp_module = fully_shard_module.FSDPModule

    class FSDPModuleABC(ABC, orig_fsdp_module):
        pass

    try:
        if isinstance(model, ABC):
            fully_shard_module.FSDPModule = FSDPModuleABC
        yield
    finally:
        fully_shard_module.FSDPModule = orig_fsdp_module


def apply_fsdp2(model, fsdp_kwargs, config):
    """model: AutoModelForCausalLM"""
    assert CPUOffloadPolicy is not None, "PyTorch version >= 2.4 is required for using fully_shard API (FSDP2)"

    default_transformer_cls_names_to_wrap = getattr(model, "_no_split_modules", None)
    fsdp_transformer_layer_cls_to_wrap = config.get("wrap_policy", {}).get(
        "transformer_layer_cls_to_wrap", default_transformer_cls_names_to_wrap
    )

    if isinstance(fsdp_transformer_layer_cls_to_wrap, str):
        fsdp_transformer_layer_cls_to_wrap = [fsdp_transformer_layer_cls_to_wrap]

    assert len(fsdp_transformer_layer_cls_to_wrap) > 0 and fsdp_transformer_layer_cls_to_wrap[0] is not None

    modules = []
    for name, module in model.named_modules():
        if module.__class__.__name__ in fsdp_transformer_layer_cls_to_wrap or (
            isinstance(module, nn.Embedding) and not model.config.tie_word_embeddings
        ):
            modules.append(module)

    for idx, module in enumerate(modules):
        # if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
        #     print(f"wrap module {module.__class__.__name__}")
        with maybe_patch_fsdp_module(module):
            fully_shard(module, **fsdp_kwargs)

    # if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
    #     print(f"wrap module {model.__class__.__name__}")
    with maybe_patch_fsdp_module(model):
        fully_shard(model, **fsdp_kwargs)  # fsdp2 will not reshard_after_forward for root module


def get_shard_placement_fn(fsdp_size):
    """Choose the dimension that can divide fsdp_size to avoid padding"""

    def shard_placement_fn(param):
        shape = list(param.shape)
        for i in range(len(shape)):
            if shape[i] % fsdp_size == 0:
                return Shard(i)
        return Shard(0)

    return shard_placement_fn


def fsdp2_clip_grad_norm_(parameters, max_norm, norm_type=2.0, error_if_nonfinite=False, foreach=None):
    """torch.nn.utils.clip_grad_norm_ cann't run on cpu parameter DTensor"""
    from torch.nn.utils.clip_grad import _clip_grads_with_norm_, _get_total_norm

    if isinstance(parameters, torch.Tensor):
        parameters = [parameters]
    else:
        # prevent generators from being exhausted
        parameters = list(parameters)
    grads = [p.grad for p in parameters if p.grad is not None]
    total_norm = _get_total_norm(grads, norm_type, error_if_nonfinite, foreach)
    total_norm = total_norm.to(get_device_id(), non_blocking=True)
    _clip_grads_with_norm_(parameters, max_norm, total_norm, foreach)
    return total_norm


def layered_summon_lora_params(fsdp_module) -> OrderedDict:
    from peft.utils.save_and_load import get_peft_model_state_dict

    def __prefix_submodules(module, prefix):
        for name, submodule in module.named_modules():
            if name.startswith(prefix) and "." not in name[len(prefix) :]:
                yield name, submodule

    lora_params = OrderedDict()
    prefix_list = [
        # fsdp
        "_fsdp_wrapped_module.base_model.model.",
        "_fsdp_wrapped_module.base_model.model.model.",
        "_fsdp_wrapped_module.base_model.model.model.layers.",
        "_fsdp_wrapped_module.base_model.model.model.language_model.layers.",
        # fsdp2
        "base_model.model.",
        "base_model.model.model.",
        "base_model.model.model.layers.",
        "base_model.model.model.language_model.layers.",
    ]
    peft_model = getattr(fsdp_module, "_fsdp_wrapped_module", fsdp_module)
    for prefix in prefix_list:
        for name, submodule in __prefix_submodules(fsdp_module, prefix):
            prefix = name.replace("_fsdp_wrapped_module.base_model.model.", "base_model.model.")
            if name.endswith(".model") or name.endswith(".layers"):
                continue
            if fsdp_version(submodule) > 0:
                with FSDP.summon_full_params(submodule, writeback=False):
                    sub_lora_params = get_peft_model_state_dict(peft_model, state_dict=submodule.state_dict())
                    sub_lora_params = {
                        f"{prefix}.{name}": param.full_tensor().detach().cpu()
                        if hasattr(param, "full_tensor")
                        else param.detach().cpu()
                        for name, param in sub_lora_params.items()
                    }
                    lora_params.update(sub_lora_params)
                    submodule._is_root = False
                get_torch_device().empty_cache()
    return lora_params


def collect_lora_params(module: FSDP, layered_summon: bool, base_sync_done: bool) -> OrderedDict:
    """
    collect lora params or full params if base model is not ready in vllm
    work with if isinstance(self.module._fsdp_wrapped_module, PeftModel)
    """
    from peft.utils.save_and_load import get_peft_model_state_dict

    lora_params = OrderedDict()
    peft_model = getattr(module, "_fsdp_wrapped_module", module)
    if fsdp_version(module) > 0:
        if layered_summon:
            if not base_sync_done:
                raise ValueError(
                    "To use layered_summon, you must make sure base-model is preloaded in vllm, e.g. let "
                    "rollout.load_format=safetensors"
                )
            lora_params = layered_summon_lora_params(module)
        else:
            with FSDP.summon_full_params(module, writeback=False):
                if base_sync_done:
                    lora_params = get_peft_model_state_dict(peft_model)
                    lora_params = {
                        name: param.full_tensor().detach().cpu()
                        if hasattr(param, "full_tensor")
                        else param.detach().cpu()
                        for name, param in lora_params.items()
                    }
                else:
                    model = peft_model.base_model.model
                    orig_dev = "cpu" if "cpu" in str(next(model.parameters()).device) else get_device_name()
                    model = model.to("cpu")
                    for name, param in model.state_dict().items():
                        if any(x in name for x in ["_flat_param", "lora_"]):
                            continue
                        name = name.replace("_fsdp_wrapped_module.", "").replace(".base_layer", "")
                        lora_params[name] = (
                            param.full_tensor().detach().cpu()
                            if hasattr(param, "full_tensor")
                            else param.detach().cpu()
                        )
                    model = model.to(orig_dev)
            get_torch_device().empty_cache()
    else:
        if base_sync_done:
            lora_params = get_peft_model_state_dict(peft_model)
        else:
            model = peft_model.base_model.model
            orig_dev = "cpu" if "cpu" in str(next(model.parameters()).device) else get_device_name()
            model = model.to("cpu")
            for name, param in model.state_dict().items():
                if any(x in name for x in ["_flat_param", "lora_"]):
                    continue
                name = name.replace("_fsdp_wrapped_module.", "").replace(".base_layer", "")
                lora_params[name] = param.detach().cpu()
            model = model.to(orig_dev)
    return lora_params


def collect_merged_peft_params(module: FSDP) -> OrderedDict:
    """Collect full model weights with the active PEFT adapter temporarily merged.

    This is used by rollout backends that cannot load a PEFT type such as DoRA
    or AdaLoRA directly.  The merge is always undone before returning so the
    actor remains in its original trainable state.
    """

    peft_model = getattr(module, "_fsdp_wrapped_module", module)

    def _collect() -> OrderedDict:
        merged_params = OrderedDict()
        peft_model.merge_adapter()
        try:
            model = peft_model.base_model.model
            for name, param in model.state_dict().items():
                if "lora_" in name:
                    continue
                name = name.replace("_fsdp_wrapped_module.", "").replace(".base_layer", "")
                merged_params[name] = (
                    param.full_tensor().detach().cpu()
                    if hasattr(param, "full_tensor")
                    else param.detach().cpu()
                )
        finally:
            peft_model.unmerge_adapter()
        return merged_params

    if fsdp_version(module) > 0:
        with FSDP.summon_full_params(module, writeback=False):
            params = _collect()

                logits = logits[:, -response_length - 1 : -1, :]  # (bsz, response_length, vocab_size)
                log_probs = logprobs_from_logits(logits, micro_batch["responses"])
                if calculate_entropy:
                    if not self.config.entropy_checkpointing:
                        entropy = verl_F.entropy_from_logits(logits)  # (bsz, response_length)
                    else:
                        entropy = torch.utils.checkpoint.checkpoint(verl_F.entropy_from_logits, logits)

        return entropy, log_probs

def _optimizer_step(self):
    assert self.config.grad_clip is not None
    if self.scaler is not None:
        self.scaler.unscale_(self.actor_optimizer)
    if isinstance(self.actor_module, FSDP):
        grad_norm = self.actor_module.clip_grad_norm_(max_norm=self.config.grad_clip)
    elif isinstance(self.actor_module, FSDPModule):
        grad_norm = fsdp2_clip_grad_norm_(self.actor_module.parameters(), max_norm=self.config.grad_clip)
    else:
        grad_norm = torch.nn.utils.clip_grad_norm_(self.actor_module.parameters(), max_norm=self.config.grad_clip)

    if isinstance(grad_norm, DTensor):
        grad_norm = grad_norm.full_tensor()

    # if grad_norm is not finite, skip the update
    if self.scaler is not None:
        self.scaler.step(self.actor_optimizer)
        self.scaler.update()
    else:
        if not torch.isfinite(grad_norm):
            print(f"WARN: rank {torch.distributed.get_rank()} grad_norm is not finite: {grad_norm}")
            self.actor_optimizer.zero_grad()
        else:
            self.actor_optimizer.step()

    peft_model = getattr(self.actor_module, "_fsdp_wrapped_module", self.actor_module)
    peft_config = getattr(getattr(peft_model, "peft_config", {}), "get", lambda *_: None)("default")
    if peft_config is not None and str(getattr(peft_config, "peft_type", "")).endswith("ADALORA"):
        init_r = getattr(peft_config, "init_r", None)
        target_r = getattr(peft_config, "target_r", None)
        should_allocate = init_r is None or target_r is None or target_r < init_r
        if should_allocate:
            missing_grad_count = 0
            for name, param in peft_model.named_parameters():
                if "lora_" in name and ".default" in name and param.grad is None:
                    # AdaLoRA rank allocation reads gradients even after optimizer.step().
                    param.grad = torch.zeros_like(param)
                    missing_grad_count += 1
            if missing_grad_count and torch.distributed.get_rank() == 0:
                print(f"Filled {missing_grad_count} missing AdaLoRA grads with zeros before rank allocation.")
            peft_model.base_model.update_and_allocate(self._adalora_step)
            self._adalora_step += 1
        elif self._adalora_step == 0 and torch.distributed.get_rank() == 0:
            print("Skipping AdaLoRA rank allocation because target_r >= init_r; rank schedule is a no-op.")
            self._adalora_step += 1
    return grad_norm

@GPUMemoryLogger(role="dp actor", logger=logger)
def compute_log_prob(self, data: DataProto, calculate_entropy=False) -> torch.Tensor:
    if not hasattr(self, "_debug_actor_compute_log_prob_once"):
        self._debug_actor_compute_log_prob_once = False
    """Compute the log probability of the responses given input_ids, attention_mask and position_ids

    Args:
        data (DataProto): a DataProto containing keys

            ``input_ids``: tensor of shape [batch_size, sequence_length]. torch.int64. Note that input_ids is the
            concatenation of prompt and response. Note that ``sequence_length = prompt_length + response_length``.

            ``attention_mask``: tensor of shape [batch_size, sequence_length]. torch.int64.

            ``position_ids``: tensor of shape [batch_size, sequence_length]. torch.int64.

            ``responses``:  tensor of shape [batch_size, response_length]. torch.int64.

    Returns:
        torch.Tensor: the log_prob tensor
    """
    # set to eval
    self.actor_module.eval()
    if not self._debug_actor_compute_log_prob_once and torch.distributed.get_rank() == 0:
        _write_actor_policy_debug(
            "actor_compute_log_prob",
            {
                "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                "rank": int(torch.distributed.get_rank()),
                **_actor_adapter_state_payload(self.actor_module),
            },
        )
        self._debug_actor_compute_log_prob_once = True

    micro_batch_size = data.meta_info["micro_batch_size"]
    temperature = data.meta_info["temperature"]  # temperature must be in the data.meta_info to avoid silent error
    use_dynamic_bsz = data.meta_info["use_dynamic_bsz"]
    has_multi_modal_inputs = "multi_modal_inputs" in data.non_tensor_batch.keys()
    select_keys = ["responses", "input_ids", "attention_mask", "position_ids"]
    non_tensor_select_keys = ["multi_modal_inputs"] if has_multi_modal_inputs else []

    data = data.select(batch_keys=select_keys, non_tensor_batch_keys=non_tensor_select_keys)

    if use_dynamic_bsz:
        max_token_len = data.meta_info["max_token_len"] * self.ulysses_sequence_parallel_size
        micro_batches, batch_idx_list = prepare_dynamic_batch(data, max_token_len=max_token_len)
    else:
        micro_batches = data.split(micro_batch_size)

    log_probs_lst = []
    entropy_lst = []
    for micro_batch in micro_batches:
        micro_batch = micro_batch.to(get_device_id())
        model_inputs = {**micro_batch.batch, **micro_batch.non_tensor_batch}
        with torch.no_grad():
            entropy, log_probs = self._forward_micro_batch(
                model_inputs, temperature=temperature, calculate_entropy=calculate_entropy
            )
        log_probs_lst.append(log_probs)
        if calculate_entropy:
            entropy_lst.append(entropy)

    log_probs = torch.concat(log_probs_lst, dim=0)
    entropys = None
    if calculate_entropy:
        entropys = torch.concat(entropy_lst, dim=0)

    if use_dynamic_bsz:
        log_probs = restore_dynamic_batch(log_probs, batch_idx_list)
        if calculate_entropy:
            entropys = restore_dynamic_batch(entropys, batch_idx_list)

    return log_probs, entropys

def _maybe_dump_full_grads(self) -> None:
    dump_path = os.getenv("VERL_FULL_GRAD_DUMP_PATH")
    if not dump_path or self._grad_dump_done or not isinstance(self.actor_module, FSDP):
        return

    requested = os.getenv("VERL_FULL_GRAD_LAYERS", "").strip()
    selected = {name.strip() for name in requested.split(",") if name.strip()}
    grad_tensors = {}

    with FSDP.summon_full_params(self.actor_module, writeback=False, with_grads=True):
        for name, param in self.actor_module.named_parameters():
            if not name.endswith(".weight"):
                continue
            if selected and name not in selected:
                continue
            if param.grad is None:
                continue
            grad_tensors[name] = param.grad.detach().cpu().float().clone()

    if torch.distributed.get_rank() == 0:
        parent = os.path.dirname(dump_path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        torch.save(grad_tensors, dump_path)
        print(f"Saved {len(grad_tensors)} full gradients to {dump_path}")

    torch.distributed.barrier()
    self._grad_dump_done = True

@GPUMemoryLogger(role="dp actor", logger=logger)
def update_policy(self, data: DataProto):
    # make sure we are in training mode
    self.actor_module.train()
    if not hasattr(self, "_debug_actor_update_policy_once"):
        self._debug_actor_update_policy_once = False
    if not self._debug_actor_update_policy_once and torch.distributed.get_rank() == 0:
        _write_actor_policy_debug(
            "actor_update_policy",
            {
                "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                "rank": int(torch.distributed.get_rank()),
                **_actor_adapter_state_payload(self.actor_module),
            },
        )
        self._debug_actor_update_policy_once = True

    temperature = data.meta_info["temperature"]  # temperature must be in the data.meta_info to avoid silent error

    select_keys = [
        "responses",
        "response_mask",
        "input_ids",
        "attention_mask",
        "position_ids",
        "old_log_probs",
        "advantages",
    ]
    if self.config.use_kl_loss:
        select_keys.append("ref_log_prob")
    safe_base_ref_log_prob = None
    if "base_ref_log_prob" in data.batch.keys():
        # TensorDict.select() corrupts this tensor in the current training path,
        # so carry a materialized copy across the selection boundary.
        safe_base_ref_log_prob = data.batch["base_ref_log_prob"].clone().contiguous()
    # Include pre-computed IS weights if present in batch
    # Weights are computed centrally in trainer and added to batch when algorithm.rollout_is=True
    if "rollout_is_weights" in data.batch.keys():
        select_keys.append("rollout_is_weights")
    # Include rollout_log_probs for computing rollout_corr metrics in bypass mode
    if "rollout_log_probs" in data.batch.keys():
        select_keys.append("rollout_log_probs")

    has_multi_modal_inputs = "multi_modal_inputs" in data.non_tensor_batch.keys()
    non_tensor_select_keys = ["multi_modal_inputs"] if has_multi_modal_inputs else []

    data = data.select(batch_keys=select_keys, non_tensor_batch_keys=non_tensor_select_keys)
    if safe_base_ref_log_prob is not None:
        data.batch["base_ref_log_prob"] = safe_base_ref_log_prob
    if (
        not self._debug_base_ref_flow_once
        and torch.distributed.get_rank() == 0
        and "base_ref_log_prob" in data.batch.keys()
    ):
        _write_base_kl_debug(
            "actor_update_probe_after_select",
            {
                "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                "rank": int(torch.distributed.get_rank()),
                **_base_ref_probe_payload(
                    "after_select",
                    data.batch["base_ref_log_prob"],
                    data.batch.get("old_log_probs"),
                ),
            },
        )

    # Split to make minibatch iterator for updating the actor
    # See PPO paper for details. https://arxiv.org/abs/1707.06347
    mini_batches = data.split(self.config.ppo_mini_batch_size)

    on_policy = len(mini_batches) == 1 and self.config.ppo_epochs == 1

    metrics = {}
    for _ in range(self.config.ppo_epochs):
        for batch_idx, mini_batch in enumerate(mini_batches):
            if (
                not self._debug_base_ref_flow_once
                and torch.distributed.get_rank() == 0
                and "base_ref_log_prob" in mini_batch.batch.keys()
            ):
                _write_base_kl_debug(
                    "actor_update_probe_mini_batch",
                    {
                        "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                        "rank": int(torch.distributed.get_rank()),
                        "mini_batch_idx": int(batch_idx),
                        **_base_ref_probe_payload(
                            "mini_batch_before_dynamic",
                            mini_batch.batch["base_ref_log_prob"],
                            mini_batch.batch.get("old_log_probs"),
                        ),
                    },
                )
            if self.config.use_dynamic_bsz:
                max_token_len = self.config.ppo_max_token_len_per_gpu * self.ulysses_sequence_parallel_size
                micro_batches, _ = prepare_dynamic_batch(mini_batch, max_token_len=max_token_len)
            else:
                self.gradient_accumulation = (
                    self.config.ppo_mini_batch_size // self.config.ppo_micro_batch_size_per_gpu
                )
                micro_batches = mini_batch.split(self.config.ppo_micro_batch_size_per_gpu)

            self.actor_optimizer.zero_grad()

            for micro_idx, micro_batch in enumerate(micro_batches):
                if (
                    not self._debug_base_ref_flow_once
                    and torch.distributed.get_rank() == 0
                    and "base_ref_log_prob" in micro_batch.batch.keys()
                ):
                    _write_base_kl_debug(
                        "actor_update_probe_micro_before_to",
                        {
                            "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                            "rank": int(torch.distributed.get_rank()),
                            "mini_batch_idx": int(batch_idx),
                            "micro_batch_idx": int(micro_idx),
                            **_base_ref_probe_payload(
                                "micro_batch_before_to",
                                micro_batch.batch["base_ref_log_prob"],
                                micro_batch.batch.get("old_log_probs"),
                            ),
                        },
                    )
                micro_batch = micro_batch.to(get_device_id())
                micro_batch_metrics = {}
                model_inputs = {**micro_batch.batch, **micro_batch.non_tensor_batch}
                if (
                    not self._debug_base_ref_flow_once
                    and torch.distributed.get_rank() == 0
                    and "base_ref_log_prob" in model_inputs
                ):
                    _write_base_kl_debug(
                        "actor_update_probe_micro_after_to",
                        {
                            "experiment_name": str(data.meta_info.get("experiment_name", "unknown_exp")),
                            "rank": int(torch.distributed.get_rank()),
                            "mini_batch_idx": int(batch_idx),
                            "micro_batch_idx": int(micro_idx),

        rollout_cls: type[BaseRollout] = get_rollout_class(rollout_config.name, rollout_config.mode)
        self.rollout = rollout_cls(
            config=rollout_config, model_config=model_config, device_mesh=rollout_device_mesh
        )

        # used for LoRA
        self.base_sync_done: bool = "dummy" not in self.config.rollout.load_format
        self.layered_summon = self.config.rollout.get("layered_summon", False)

